(5, 'امنیت فناوری اطلاعات', 'security', 'بازبینی و امن‌سازی سایت، سرور و زیرساخت.', 5, 1);
INSERT IGNORE INTO services (id, category_id, title, slug, short_description, description, scope_includes, delivery_note, is_active, display_order) VALUES
(1, 1, 'طراحی سایت شرکتی و فروشگاهی', 'website-design', 'طراحی تجربه‌ای روشن برای معرفی کسب‌وکار، خدمات و محصولات شما.', 'نیازسنجی، طراحی ساختار صفحات و توسعه وب‌سایت متناسب با هدف کسب‌وکار. محدوده، محتوا و امکانات هر پروژه پیش از شروع در پیش‌فاکتور مشخص می‌شود.', 'نیازسنجی و ساختار صفحات؛ طراحی واکنش‌گرا؛ پیاده‌سازی و تحویل مستندات توافق‌شده', 'زمان و محدوده اجرا پس از بررسی نیازمندی‌ها اعلام می‌شود.', 1, 1),
(2, 1, 'توسعه نرم‌افزار اختصاصی', 'custom-software', 'توسعه قابلیت‌ها و سامانه‌های اختصاصی بر اساس فرایند کسب‌وکار.', 'طراحی و توسعه ماژول‌ها و نرم‌افزارهای اختصاصی، از تحلیل مسئله تا پیاده‌سازی و استقرار.', 'تحلیل نیاز؛ تعریف محدوده؛ توسعه ماژول‌های توافق‌شده؛ تحویل مستندات', 'برآورد زمانی و مالی پس از دریافت نیازمندی‌ها انجام می‌شود.', 1, 2),
(3, 1, 'WordPress و WooCommerce', 'wordpress-woocommerce', 'راه‌اندازی، توسعه و نگهداری وب‌سایت و فروشگاه مبتنی بر WordPress.', 'نصب و پیکربندی WordPress یا WooCommerce، بهینه‌سازی و توسعه امکانات در محدوده مورد توافق.', 'راه‌اندازی و پیکربندی؛ انتقال سایت؛ رفع خطا و بهینه‌سازی؛ توسعه امکانات', 'هزینه افزونه‌ها، قالب‌ها و سرویس‌های ثالث جداگانه بررسی می‌شود.', 1, 3),
(4, 2, 'DevOps و استقرار نرم‌افزار', 'devops-deployment', 'استقرار و نگهداری برنامه‌ها با ابزارهایی مانند Linux، Docker و CI/CD.', 'پیکربندی سرور و وب‌سرور، استقرار برنامه، کانتینرسازی و خودکارسازی فرایندهای تحویل.', 'Linux؛ Docker و Docker Compose؛ Git و CI/CD؛ SSL؛ مانیتورینگ و بکاپ', 'دسترسی‌ها و شرایط میزبانی پیش از شروع بررسی می‌شوند.', 1, 4),
(5, 3, 'پشتیبانی IT و Help Desk', 'it-helpdesk', 'پشتیبانی کاربران و نگهداری دوره‌ای سامانه‌های فناوری اطلاعات.', 'خدمات پشتیبانی غیرحضوری یا حضوری، عیب‌یابی و نگهداری با محدوده و زمان پاسخ توافق‌شده.', 'پشتیبانی کاربران؛ نصب و پیکربندی نرم‌افزار؛ عیب‌یابی؛ نگهداری دوره‌ای', 'خدمات حضوری بر اساس محدوده جغرافیایی و توافق قراردادی ارائه می‌شود.', 1, 5),
(6, 4, 'شبکه و زیرساخت', 'network-infrastructure', 'راه‌اندازی شبکه داخلی، تجهیزات و مستندسازی زیرساخت.', 'طراحی و اجرای شبکه داخلی، تنظیم روتر و سوئیچ، Wi-Fi و زیرساخت پسیو در صورت امکان اجرا.', 'ارزیابی نیاز؛ شبکه داخلی و بی‌سیم؛ تنظیم تجهیزات؛ مستندسازی', 'بازدید حضوری و هزینه تجهیزات در پیش‌فاکتور جداگانه مشخص می‌شوند.', 1, 6),
(7, 5, 'امنیت و امن‌سازی زیرساخت', 'it-security', 'بازبینی دسترسی‌ها، امنیت سایت و سرور و فرایندهای پشتیبان‌گیری.', 'بررسی و ارائه پیشنهادهای اجرایی برای کاهش ریسک در سایت، سرور و زیرساخت فناوری اطلاعات.', 'بازبینی دسترسی؛ امن‌سازی سرور؛ بررسی بکاپ و به‌روزرسانی؛ پیشنهادهای DevSecOps', 'خدمات امنیتی فقط با مجوز کتبی و محدوده آزمون مشخص انجام می‌شوند.', 1, 7);
